import os
from pathlib import Path

import pytest


def read_public(path: str) -> str:
    """Return the text of the file `path` inside the directory `notes`.

    `notes` is relative to the working directory. `path` is an untrusted
    request path and may include subdirectories (`sub/b.txt`). A path that
    wanders but stays inside `notes` (`sub/../a.txt`) is allowed. Any path
    that leaves `notes` (`..`, an absolute path, `sub/../../x`, or a
    symlink resolving outside `notes`) reads nothing. A missing,
    unreadable, or non-file target gives an empty string.
    """
    try:
        if os.path.isabs(path) or path.startswith(("/", "\\")):
            return ""
        if Path(path).is_absolute() or Path(path).drive:
            return ""
        base = Path("notes").resolve()
        target = (base / path).resolve()
        if not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("hello")
    (notes / "sub" / "b.txt").write_text("bee")
    (tmp_path / "secret.txt").write_text("secret")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "x.txt").write_text("sibling")
    return tmp_path


def test_reads_top_level_file(root: Path) -> None:
    assert read_public("a.txt") == "hello"


def test_reads_subdirectory_file(root: Path) -> None:
    assert read_public("sub/b.txt") == "bee"


def test_wander_and_return_is_allowed(root: Path) -> None:
    assert read_public("sub/../a.txt") == "hello"
    assert read_public("./a.txt") == "hello"
    assert read_public("sub/./b.txt") == "bee"


def test_missing_file_is_empty(root: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""
    assert read_public("nodir/nope.txt") == ""


def test_empty_path_and_directories_are_empty(root: Path) -> None:
    assert read_public("") == ""
    assert read_public(".") == ""
    assert read_public("sub") == ""
    assert read_public("sub/") == ""


def test_parent_traversal_is_empty(root: Path) -> None:
    assert read_public("..") == ""
    assert read_public("../secret.txt") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("sub/../../x") == ""
    assert read_public("a.txt/../../secret.txt") == ""


def test_sibling_with_same_prefix_is_empty(root: Path) -> None:
    assert read_public("../notes2/x.txt") == ""
    assert read_public("sub/../../notes2/x.txt") == ""


def test_absolute_path_is_empty(root: Path) -> None:
    assert read_public(str(root / "secret.txt")) == ""
    assert read_public(str(root / "notes" / "a.txt")) == ""
    assert read_public("/etc/passwd") == ""
    assert read_public("//etc/passwd") == ""


def test_symlink_file_escaping_is_empty(root: Path) -> None:
    link = root / "notes" / "link.txt"
    try:
        link.symlink_to(root / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert read_public("link.txt") == ""


def test_symlink_dir_escaping_is_empty(root: Path) -> None:
    link = root / "notes" / "outdir"
    try:
        link.symlink_to(root / "notes2", target_is_directory=True)
    except OSError:
        pytest.skip("symlinks not supported")
    assert read_public("outdir/x.txt") == ""


def test_symlink_staying_inside_is_allowed(root: Path) -> None:
    link = root / "notes" / "alias.txt"
    try:
        link.symlink_to(root / "notes" / "a.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert read_public("alias.txt") == "hello"


def test_symlink_loop_is_empty(root: Path) -> None:
    loop = root / "notes" / "loop"
    try:
        loop.symlink_to(loop)
    except OSError:
        pytest.skip("symlinks not supported")
    assert read_public("loop") == ""


def test_nul_byte_is_empty(root: Path) -> None:
    assert read_public("a.txt\x00") == ""
    assert read_public("\x00") == ""


def test_undecodable_file_is_empty(root: Path) -> None:
    (root / "notes" / "bin.dat").write_bytes(b"\xff\xfe\x00\xff")
    assert read_public("bin.dat") == ""


@pytest.mark.skipif(os.name == "nt", reason="permission bits are POSIX")
def test_unreadable_file_is_empty(root: Path) -> None:
    p = root / "notes" / "locked.txt"
    p.write_text("x")
    p.chmod(0)
    try:
        assert read_public("locked.txt") == ""
    finally:
        p.chmod(0o644)


def test_working_directory_with_notes_name_inside_path(root: Path) -> None:
    (root / "notes" / "notes").mkdir()
    (root / "notes" / "notes" / "c.txt").write_text("inner")
    assert read_public("notes/c.txt") == "inner"
    assert read_public("notes/../a.txt") == "hello"

